def count_positive(numbers):
    count = 0
    for number in numbers:
        if number > 0:
            count += 1
    return count

def find_max(numbers):
    if not numbers:
        return None
    best = numbers[0]
    for number in numbers[1:]:
        if number > best:
            best = number
    return best

