def binary_search(items, target):
    low = 0
    high = len(items) - 1
    while low <= high:
        mid = (low + high) // 2
        guess = items[mid]
        if guess == target:
            return mid
        if guess < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1

def recursive_sum(numbers):
    if not numbers:
        return 0
    return numbers[0] + recursive_sum(numbers[1:])

def fib(n):
    memo = {0: 0, 1: 1}

    def calc(k):
        if k in memo:
            return memo[k]
        memo[k] = calc(k - 1) + calc(k - 2)
        return memo[k]

    return calc(n)
